// Shared date helpers.
//
// NOTE: the various getDateStr/getDatetime methods scattered across the views
// are deceptively different and are intentionally NOT all consolidated here:
//   - assign/assigning.vue getDatetime() includes the year; result.vue's does not
//   - Holiday.vue / listAllCases.vue getDateStr(dateValue) take a date value,
//     not a day offset
// Only the genuinely-identical offset→"YYYY-M-D" helper lives here.

// "YYYY-M-D" for a day `offset` (may be a number or numeric string) relative to
// today. parseInt guards against `getDate() + "3"` becoming string concatenation.
export function dateStrFromOffset(offset) {
  const today = new Date()
  today.setDate(today.getDate() + parseInt(offset))
  return today.getFullYear() + '-' + (today.getMonth() + 1) + '-' + today.getDate()
}
